TelemetryEventServiceAsyncWaiter::TelemetryEventServiceAsyncWaiter(
    TelemetryEventService* proxy) : proxy_(proxy) {}

TelemetryEventServiceAsyncWaiter::~TelemetryEventServiceAsyncWaiter() = default;

void TelemetryEventServiceAsyncWaiter::IsEventSupported(
    TelemetryEventCategoryEnum category, ::crosapi::mojom::TelemetryExtensionSupportStatusPtr* out_status) {
  base::RunLoop loop;
  proxy_->IsEventSupported(std::move(category),
      base::BindOnce(
          [](base::RunLoop* loop,
             ::crosapi::mojom::TelemetryExtensionSupportStatusPtr* out_status
,
             ::crosapi::mojom::TelemetryExtensionSupportStatusPtr status) {*out_status = std::move(status);
            loop->Quit();
          },
          &loop,
          out_status));
  loop.Run();
}

::crosapi::mojom::TelemetryExtensionSupportStatusPtr TelemetryEventServiceAsyncWaiter::IsEventSupported(
    TelemetryEventCategoryEnum category) {
  ::crosapi::mojom::TelemetryExtensionSupportStatusPtr async_wait_result;
  IsEventSupported(std::move(category),&async_wait_result);
  return async_wait_result;
}






